// Парсимо JSON від моделі + збагачуємо даними листа (для КОЖНОГО листа окремо)
const ai = $json.message?.content ?? $json.content ?? $json.text;
const email = $('Gmail Trigger').item.json;

const ALLOWED = {
  priority: ['P1', 'P2', 'P3', 'P4'],
  category: ['доставка', 'повернення', 'оплата', 'брак', 'товар', 'інше'],
  sentiment: ['positive', 'neutral', 'negative'],
};

let parsed;
let parseError = false;
try {
  parsed = typeof ai === 'string'
    ? JSON.parse(ai.replace(/^```(json)?/i, '').replace(/```$/, '').trim())
    : ai;
  if (!parsed || typeof parsed !== 'object') throw new Error('empty');
} catch (e) {
  parseError = true;
  parsed = {};
}

// Безпечні значення за замовчуванням: щось незрозуміле -> людина
const priority = ALLOWED.priority.includes(parsed.priority) ? parsed.priority : 'P2';
const category = ALLOWED.category.includes(parsed.category) ? parsed.category : 'інше';
const sentiment = ALLOWED.sentiment.includes(parsed.sentiment) ? parsed.sentiment : 'neutral';
let requiresHuman = parsed.requires_human === true || parsed.requires_human === 'true' || parseError;
if (['P1', 'P2'].includes(priority)) requiresHuman = true;   // жорстке правило ескалації

const action = ['P1', 'P2'].includes(priority) ? 'draft-escalation'
  : priority === 'P3' && !requiresHuman ? 'auto-reply'
  : priority === 'P3' ? 'draft-needs-human'
  : 'label-only';

// Страховка: підпис бренду, якщо модель його забула (ітерація 1)
const SIGNATURE = 'Команда підтримки HouseBox';
let reply = typeof parsed.suggested_response === 'string' ? parsed.suggested_response.trim() : '';
if (reply && !reply.includes(SIGNATURE)) reply += '\n\n' + SIGNATURE;
if (reply) parsed.suggested_response = reply;

const from = email.from?.value?.[0] ?? {};
return {
  json: {
    email_id: email.id,
    thread_id: email.threadId,
    received_at: new Date(email.date ?? Date.now()).toISOString(),
    from_email: from.address ?? '',
    from_name: from.name ?? '',
    subject: email.subject ?? '(без теми)',
    priority,
    category,
    sentiment,
    requires_human: requiresHuman,
    action,
    escalation_reason: parsed.escalation_reason ?? (parseError ? 'AI повернув невалідний JSON' : ''),
    order_number: parsed.order_number ?? '',
    suggested_response: parsed.suggested_response ??
      'Дякуємо за звернення! Менеджер HouseBox відповість вам протягом робочого дня.\n\nКоманда підтримки HouseBox',
    parse_error: parseError,
  },
};
